/* xx_qrst_extractor.c - search raw data for QRST.
 *
 * Scans for:
 *   51 52 53 54 00 00 80 3F at +0  ("QRST...?")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the qrst reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/qrst/xx_qrst.h"

static const uint8_t k_anchor0[] = { 0x51, 0x52, 0x53, 0x54, 0x00, 0x00, 0x80, 0x3F };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_QRST };

static Abstractformat *xx_qrst_search_open(xx_io_device *window) {
    xx_qrst *reader = xx_qrst_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_qrst_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_qrst_free((xx_qrst *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_qrst_search_open, xx_qrst_search_close
};

static xx_format_search_state *xx_qrst_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_qrst_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_qrst_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_qrst_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_qrst_extractor = {
    xx_qrst_create_format_search,
    xx_qrst_get_current_format_info,
    xx_qrst_format_search_find_next,
    xx_qrst_free_format_search
};
